#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;
const ELF_PATH = process.env.MIPS_ELF || path.join(ROOT, 'doomgeneric_mips');
const FRAME_LIMIT = Number.parseInt(process.env.MAX_FRAMES || '1', 10);
const STACK_TOP = 0x7ff00000;
const CHUNK_BITS = 20;
const CHUNK_SIZE = 1 << CHUNK_BITS;
function u32(value) {
  return value >>> 0;
}

function s32(value) {
  return value | 0;
}

function sign16(value) {
  return (value & 0x8000) ? (value | 0xffff0000) : value;
}

function sign8(value) {
  return (value & 0x80) ? (value | 0xffffff00) : value;
}

function addAddress(base, offset) {
  return (base + sign16(offset)) >>> 0;
}

class GuestMemory {
  constructor() {
    // Chunks are allocated on demand. This preserves the ELF's one-GiB static
    // heap without reserving or clearing a one-GiB host buffer.
    this.chunks = [];
  }

  chunk(address, allocate) {
    const index = address >>> CHUNK_BITS;
    let chunk = this.chunks[index];
    if (!chunk && allocate) {
      chunk = Buffer.alloc(CHUNK_SIZE);
      this.chunks[index] = chunk;
    }
    return chunk;
  }

  read8(address) {
    const chunk = this.chunk(address, false);
    return chunk ? chunk[address & (CHUNK_SIZE - 1)] : 0;
  }

  read16(address) {
    const chunk = this.chunk(address, false);
    const offset = address & (CHUNK_SIZE - 1);
    if (chunk && offset <= CHUNK_SIZE - 2) return chunk.readUInt16LE(offset);
    return this.read8(address) | (this.read8((address + 1) >>> 0) << 8);
  }

  read32(address) {
    const chunk = this.chunk(address, false);
    const offset = address & (CHUNK_SIZE - 1);
    if (chunk && offset <= CHUNK_SIZE - 4) return chunk.readUInt32LE(offset);
    return this.read8(address) |
      (this.read8((address + 1) >>> 0) << 8) |
      (this.read8((address + 2) >>> 0) << 16) |
      (this.read8((address + 3) >>> 0) << 24);
  }

  write8(address, value) {
    this.chunk(address, true)[address & (CHUNK_SIZE - 1)] = value & 0xff;
  }

  write16(address, value) {
    const chunk = this.chunk(address, true);
    const offset = address & (CHUNK_SIZE - 1);
    value >>>= 0;
    if (offset <= CHUNK_SIZE - 2) {
    this.steps++;
  }

  run() {
    while (!this.halted && this.steps < this.maxSteps) this.step();
    if (!this.halted) throw new Error(`step limit ${this.maxSteps} reached at PC 0x${this.pc.toString(16)}`);
  }
}

function parseElf(image) {
  if (image.readUInt32LE(0) !== 0x464c457f) throw new Error(`${ELF_PATH} is not an ELF file`);
  if (image[4] !== 1 || image[5] !== 1) throw new Error('expected a little-endian ELF32 image');
  const entry = image.readUInt32LE(24);
  const phoff = image.readUInt32LE(28);
  const phentsize = image.readUInt16LE(42);
  const phnum = image.readUInt16LE(44);
  const loadSegments = [];
  for (let i = 0; i < phnum; i++) {
    const offset = phoff + i * phentsize;
    const type = image.readUInt32LE(offset);
    if (type !== 1) continue;
    loadSegments.push({
      offset: image.readUInt32LE(offset + 4),
      vaddr: image.readUInt32LE(offset + 8),
      fileSize: image.readUInt32LE(offset + 16),
      memorySize: image.readUInt32LE(offset + 20),
    });
  }
  return { entry, loadSegments };
}

function main() {
  const image = fs.readFileSync(ELF_PATH);
  const elf = parseElf(image);
  const vm = new MipsVM(image, elf);
  try {
    vm.run();
  } catch (error) {
    if (!(error instanceof HaltExecution)) throw error;
  } finally {
    vm.host.finishOutput();
  }
  process.stderr.write(`MIPS execution stopped after ${vm.steps} instructions at 0x${vm.pc.toString(16)}\n`);
}

if (require.main === module) main();

module.exports = { GuestMemory, MipsVM, parseElf };

